jQuery(function ($) {

  $('body').on('click', '.button-favorite__favorite', function (e) {
    var currentElement = $(this);
    var currentFavoriteID = $(this).data('id');
    var hasFavorited = $(this).hasClass('button-favorite__favorite--favorited');
    var hasBlocked = $(this).hasClass('button-favorite__favorite--blocked');
    var inProcessLoading = $(this).hasClass('button-favorite__favorite--saving');
    var existRemoveElementInPage = $(this).closest('.page-favorite__box-loop');

    if (!inProcessLoading && !hasBlocked) {
      $('.button-favorite__favorite').addClass('button-favorite__favorite--blocked');
      currentElement.addClass('button-favorite__favorite--saving');

      var dataToFavorite = {
        'action': 'set_favorite_post',
        'postID': currentFavoriteID,
        '_favorite_page': aemi_favorite_scripts._favorite_page,
        'favorite': (!hasFavorited)
      };

      $.ajax({
        url: aemi_favorite_scripts.ajax_url,
        type: "POST",
        dataType: 'json',
        data: dataToFavorite,
        success: function (result) {
          //case success
          if (result.success) {

            if ((!hasFavorited)) {
              currentElement.addClass('button-favorite__favorite--favorited');
            } else {
              currentElement.removeClass('button-favorite__favorite--favorited');

              if (existRemoveElementInPage.length > 0) {
                existRemoveElementInPage.remove();

                //add 
                if ($('.page-favorite__box-loop').length == 0) {
                  $('.page-favorite__container > .row').append('<div class="page-favorite__no-content"><h2>' + ($('.page-favorite__container').data('titlenoresult')) + '</h2></div>');
                }
              }
            }

          }
          currentElement.removeClass('button-favorite__favorite--saving');
          $('.button-favorite__favorite').removeClass('button-favorite__favorite--blocked');
        },
        error: function (error) {
          currentElement.removeClass('button-favorite__favorite--saving');
          $('.button-favorite__favorite').removeClass('button-favorite__favorite--blocked');
        }
      });
    }

  });
});